INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Pluto', 'Venus', 'quincunx', 'Góc bất bất hợp (150°) đòi hỏi sự tái điều chỉnh liên tục giữa Sao Diêm Vương (sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh) và Sao Kim (tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ). Hai nguồn năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn cần chủ động sắp xếp để sức mạnh chuyển hóa, chiều sâu tâm lý và sự tái sinh không làm gián đoạn hoặc gây mâu thuẫn với tình yêu, cảm xúc lãng mạn và giá trị thẩm mỹ.', 'Khả năng giải quyết vấn đề tháo vát, tinh thần linh hoạt và năng lực thích nghi với các tình huống bất ngờ. (Sao Diêm Vương - Sao Kim)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Diêm Vương - Sao Kim)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Diêm Vương', 'Sao Kim']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'conjunction', 'Góc trùng hợp mang lại sự hợp nhất mãnh liệt giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai nguồn năng lượng hòa cùng một nhịp, định hình một nét cá tính nổi bật và nhất quán.', 'Trong cuộc sống hàng ngày, bạn thể hiện sự gắn kết tự nhiên giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và năng lượng hành động, lòng dũng cảm và ham muốn chinh phục. Mọi phản ứng diễn ra trực tiếp, bộc phát theo bản năng thống nhất của cả hai hành tinh.', 'Sự tập trung năng lượng cao, tinh thần nhất quán nội tâm và khả năng bộc lộ cá tính ấn tượng. (Sao Mộc - Sao Hỏa)', 'Đôi khi khó tách bạch các góc nhìn khác nhau. Dễ bị cuốn vào sự chủ quan khi hai nguồn năng lượng quá hòa nhập. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'sextile', 'Góc lục hợp tạo cơ hội thuận lợi và sự hỗ trợ nhịp nhàng giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Năng lượng tuôn chảy nhẹ nhàng, kích thích tiềm năng phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp niềm tin, sự may mắn và khát vọng phát triển tri thức với năng lượng hành động, lòng dũng cảm và ham muốn chinh phục để gặt hái kết quả tích cực và nắm bắt cơ hội một cách hiệu quả.', 'Sự linh hoạt trong tư duy, kỹ năng kết nối tốt và tinh thần chủ động học hỏi, thích ứng nhanh. (Sao Mộc - Sao Hỏa)', 'Nếu không tự giác đặt ra thách thức và hành động, các cơ hội thuận lợi có thể bị trôi qua một cách thụ động. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và năng lượng hành động, lòng dũng cảm và ham muốn chinh phục diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Mộc - Sao Hỏa)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'square', 'Góc vuông góc tạo ra sự căng thẳng và thử thách nội tâm giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa đòi hỏi về niềm tin, sự may mắn và khát vọng phát triển tri thức và nhu cầu về năng lượng hành động, lòng dũng cảm và ham muốn chinh phục.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng chuyển hóa áp lực xung đột thành sức mạnh bứt phá. (Sao Mộc - Sao Hỏa)', 'Dễ rơi vào trạng thái căng thẳng thần kinh hoặc bực bội nội tâm khi chưa học được cách dung hòa hai năng lượng. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'opposition', 'Góc xung chiếu tạo sự đối lập và đòi hỏi sự cân bằng giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai mặt của một trục năng lượng cần được dung hòa hài hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là niềm tin, sự may mắn và khát vọng phát triển tri thức và bên kia là năng lượng hành động, lòng dũng cảm và ham muốn chinh phục, thường phản chiếu qua các mối quan hệ.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, hòa giải tuyệt vời khi đã trưởng thành. (Sao Mộc - Sao Hỏa)', 'Cảm giác dao động mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ người khác trước khi đạt được sự cân bằng. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Jupiter', 'Mars', 'semi-sextile', 'Góc bán lục hợp mang đến sự tương tác tinh tế giữa Sao Mộc (niềm tin, sự may mắn và khát vọng phát triển tri thức) và Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục). Hai năng lượng kề nhau thúc đẩy sự tinh chỉnh vi mô liên tục.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những góc nhìn khác biệt nhỏ giữa niềm tin, sự may mắn và khát vọng phát triển tri thức và năng lượng hành động, lòng dũng cảm và ham muốn chinh phục, đòi hỏi sự linh hoạt điều chỉnh trong ứng xử.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và năng lực thích ứng linh hoạt. (Sao Mộc - Sao Hỏa)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và đáp ứng các nhu cầu vi mô của bản thân. (Sao Mộc - Sao Hỏa)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Sao Mộc', 'Sao Hỏa']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
