INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Uranus', 'square', 'Góc vuông góc tạo ra sự căng thẳng và thử thách nội tâm giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa đòi hỏi về năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và nhu cầu về tư duy đổi mới, tính độc lập và sự đột phá.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng chuyển hóa áp lực xung đột thành sức mạnh bứt phá. (Sao Hỏa - Sao Thiên Vương)', 'Dễ rơi vào trạng thái căng thẳng thần kinh hoặc bực bội nội tâm khi chưa học được cách dung hòa hai năng lượng. (Sao Hỏa - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Hỏa', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Uranus', 'opposition', 'Góc xung chiếu tạo sự đối lập và đòi hỏi sự cân bằng giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Hai mặt của một trục năng lượng cần được dung hòa hài hòa.', 'Trong cuộc sống hàng ngày, bạn hay thấy mình đứng giữa hai cực: một bên là năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và bên kia là tư duy đổi mới, tính độc lập và sự đột phá, thường phản chiếu qua các mối quan hệ.', 'Tầm nhìn khách quan đa chiều, khả năng thấu hiểu tâm lý đối phương và năng lực đàm phán, hòa giải tuyệt vời khi đã trưởng thành. (Sao Hỏa - Sao Thiên Vương)', 'Cảm giác dao động mâu thuẫn giữa nhu cầu cá nhân và kỳ vọng từ người khác trước khi đạt được sự cân bằng. (Sao Hỏa - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Xung Chiếu', 'Sao Hỏa', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Uranus', 'semi-sextile', 'Góc bán lục hợp mang đến sự tương tác tinh tế giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Hai năng lượng kề nhau thúc đẩy sự tinh chỉnh vi mô liên tục.', 'Trong cuộc sống hàng ngày, bạn nhận thấy những góc nhìn khác biệt nhỏ giữa năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và tư duy đổi mới, tính độc lập và sự đột phá, đòi hỏi sự linh hoạt điều chỉnh trong ứng xử.', 'Khả năng quan sát tinh tế, sự nhạy cảm với các chi tiết nhỏ và năng lực thích ứng linh hoạt. (Sao Hỏa - Sao Thiên Vương)', 'Cảm giác lấn cấn nhỏ dai dẳng nếu không chú ý lắng nghe và đáp ứng các nhu cầu vi mô của bản thân. (Sao Hỏa - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Bán Lục Hợp', 'Sao Hỏa', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Uranus', 'quincunx', 'Góc bất bất hợp (150°) đòi hỏi sự tái điều chỉnh liên tục giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Thiên Vương (tư duy đổi mới, tính độc lập và sự đột phá). Hai nguồn năng lượng không có điểm chung tự nhiên.', 'Trong cuộc sống hàng ngày, bạn cần chủ động sắp xếp để năng lượng hành động, lòng dũng cảm và ham muốn chinh phục không làm gián đoạn hoặc gây mâu thuẫn với tư duy đổi mới, tính độc lập và sự đột phá.', 'Khả năng giải quyết vấn đề tháo vát, tinh thần linh hoạt và năng lực thích nghi với các tình huống bất ngờ. (Sao Hỏa - Sao Thiên Vương)', 'Dễ bị mệt mỏi tinh thần hoặc căng thẳng sức khỏe nhẹ do phải liên tục điều chỉnh nhịp sống. (Sao Hỏa - Sao Thiên Vương)', '', '', ARRAY['Góc chiếu Bất Bất Hợp', 'Sao Hỏa', 'Sao Thiên Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Neptune', 'conjunction', 'Góc trùng hợp mang lại sự hợp nhất mãnh liệt giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Hải Vương (trực giác tâm linh, trí tưởng tượng và lòng vị tha). Hai nguồn năng lượng hòa cùng một nhịp, định hình một nét cá tính nổi bật và nhất quán.', 'Trong cuộc sống hàng ngày, bạn thể hiện sự gắn kết tự nhiên giữa năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và trực giác tâm linh, trí tưởng tượng và lòng vị tha. Mọi phản ứng diễn ra trực tiếp, bộc phát theo bản năng thống nhất của cả hai hành tinh.', 'Sự tập trung năng lượng cao, tinh thần nhất quán nội tâm và khả năng bộc lộ cá tính ấn tượng. (Sao Hỏa - Sao Hải Vương)', 'Đôi khi khó tách bạch các góc nhìn khác nhau. Dễ bị cuốn vào sự chủ quan khi hai nguồn năng lượng quá hòa nhập. (Sao Hỏa - Sao Hải Vương)', '', '', ARRAY['Góc chiếu Trùng Hợp', 'Sao Hỏa', 'Sao Hải Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Neptune', 'sextile', 'Góc lục hợp tạo cơ hội thuận lợi và sự hỗ trợ nhịp nhàng giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Hải Vương (trực giác tâm linh, trí tưởng tượng và lòng vị tha). Năng lượng tuôn chảy nhẹ nhàng, kích thích tiềm năng phát triển.', 'Trong cuộc sống hàng ngày, bạn dễ dàng kết hợp năng lượng hành động, lòng dũng cảm và ham muốn chinh phục với trực giác tâm linh, trí tưởng tượng và lòng vị tha để gặt hái kết quả tích cực và nắm bắt cơ hội một cách hiệu quả.', 'Sự linh hoạt trong tư duy, kỹ năng kết nối tốt và tinh thần chủ động học hỏi, thích ứng nhanh. (Sao Hỏa - Sao Hải Vương)', 'Nếu không tự giác đặt ra thách thức và hành động, các cơ hội thuận lợi có thể bị trôi qua một cách thụ động. (Sao Hỏa - Sao Hải Vương)', '', '', ARRAY['Góc chiếu Lục Hợp', 'Sao Hỏa', 'Sao Hải Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Neptune', 'trine', 'Góc tam hợp mang lại dòng chảy hài hòa và sự may mắn tự nhiên giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Hải Vương (trực giác tâm linh, trí tưởng tượng và lòng vị tha). Hai hành tinh bổ trợ cho nhau một cách hoàn hảo.', 'Trong cuộc sống hàng ngày, sự kết hợp giữa năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và trực giác tâm linh, trí tưởng tượng và lòng vị tha diễn ra vô cùng tự nhiên, không gặp phải sự gượng ép hay trở ngại đáng kể.', 'Tài năng bẩm sinh, sự an ổn trong tâm hồn, sức hút tự nhiên và khả năng gặt hái thành công trôi chảy. (Sao Hỏa - Sao Hải Vương)', 'Có nguy cơ sinh ra tâm lý tự mãn hoặc thiếu động lực bứt phá khi đối mặt với những thử thách thực sự lớn. (Sao Hỏa - Sao Hải Vương)', '', '', ARRAY['Góc chiếu Tam Hợp', 'Sao Hỏa', 'Sao Hải Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
INSERT INTO placement_interpretations (language, factor_type, factor_value_1, factor_value_2, factor_value_3, core_meaning, real_life, strengths, challenges, relationships, growth_path, key_themes) VALUES ('vi', 'aspect', 'Mars', 'Neptune', 'square', 'Góc vuông góc tạo ra sự căng thẳng và thử thách nội tâm giữa Sao Hỏa (năng lượng hành động, lòng dũng cảm và ham muốn chinh phục) và Sao Hải Vương (trực giác tâm linh, trí tưởng tượng và lòng vị tha). Đây là động lực áp lực thúc đẩy sự trưởng thành vượt bậc.', 'Trong cuộc sống hàng ngày, bạn thường xuyên cảm thấy sự giằng xé giữa đòi hỏi về năng lượng hành động, lòng dũng cảm và ham muốn chinh phục và nhu cầu về trực giác tâm linh, trí tưởng tượng và lòng vị tha.', 'Ý chí kiên cường, bản lĩnh vượt khó phi thường và khả năng chuyển hóa áp lực xung đột thành sức mạnh bứt phá. (Sao Hỏa - Sao Hải Vương)', 'Dễ rơi vào trạng thái căng thẳng thần kinh hoặc bực bội nội tâm khi chưa học được cách dung hòa hai năng lượng. (Sao Hỏa - Sao Hải Vương)', '', '', ARRAY['Góc chiếu Vuông Góc', 'Sao Hỏa', 'Sao Hải Vương']) ON CONFLICT (language, factor_type, factor_value_1, factor_value_2, factor_value_3) DO UPDATE SET core_meaning = EXCLUDED.core_meaning, real_life = EXCLUDED.real_life, strengths = EXCLUDED.strengths, challenges = EXCLUDED.challenges, key_themes = EXCLUDED.key_themes;
